async (page) => {
 const results=[], errors=[];
 page.on('pageerror',e=>errors.push(e.message));
 page.on('dialog',d=>d.accept());
 await page.goto('http://127.0.0.1:18423/prototype.html?revision=final');
 const visit=async path=>{await page.evaluate(path=>go(path),path);await page.waitForFunction(path=>route===path.split('?')[0] && query.toString()===new URLSearchParams(path.split('?')[1]||'').toString(),path);};
 const assert=async(name,condition)=>{if(!condition)throw Error(name);results.push(name)};
 const stored=key=>page.evaluate(key=>JSON.parse(sessionStorage.getItem('studio.'+key)||'null'),key);
 const submit=type=>page.locator('form[data-form='+type+'] button[type=submit],form[data-form='+type+'] button:not([type])').last().click();
 await page.locator('[data-action=reset]').click();
 await visit('/new?recipe=reasoning');
 await assert('方案库复制覆盖、标准、质量组合',!!(await stored('brief')).recipe && await page.locator('main').innerText().then(t=>t.includes('已复制')));
 await page.locator('input[name=name]').fill('GRPO 奖励实验');await page.locator('input[value=GRPO]').check();await submit('brief');
 await page.waitForFunction(()=>route==='/new/coverage');
 await page.locator('input[name=n]').fill('2');await page.locator('input[name=m]').fill('3');await page.locator('input[name=x]').fill('10');
 await assert('n × m × x 实时计数',await page.locator('#scale').innerText()==='60 个目标问题');
 await submit('brief');await page.waitForFunction(()=>route==='/new/quality');await submit('brief');await page.waitForFunction(()=>route==='/p/boreal/blueprint');
 await assert('GRPO 项目隔离与方案继承',(await stored('boreal.name'))==='GRPO 奖励实验' && (await stored('boreal.recipe'))==='reasoning-v3' && !(await stored('aurora.name')));
 await visit('/p/boreal/quality/new');await page.locator('input[value=Orion]').uncheck();await page.locator('input[value=Nova]').uncheck();await submit('experiment');
 await assert('无裁判阻止提交',await page.locator('#toast').innerText()==='至少选择一个独立裁判');
 await page.locator('input[value=Orion]').check();await submit('experiment');await page.waitForFunction(()=>route.endsWith('/quality/e9'));
 await assert('实验先排队，未给最终结论',(await page.locator('main').innerText()).includes('未就绪'));
 await page.waitForFunction(()=>document.querySelector('h1')?.textContent.includes('奖励材料质量报告'));
 await assert('GRPO 报告类型、1 条样本与来源一致',(await page.locator('main').innerText()).includes('档位覆盖') && (await stored('boreal.experiment')).ids.join(',')==='g201');
 await visit('/p/boreal/data/g201/history');await assert('GRPO 来源 G07',(await page.locator('main').innerText()).includes('G07'));
 await visit('/p/aurora/blueprint');await page.locator('a[aria-label="选择独立评估"]').click();await page.waitForFunction(()=>query.get('node')==='evaluation');
 await page.locator('input[name=concurrency]').fill('7');await page.locator('a[href="#/p/aurora/data"]').click();
 await assert('未保存导航确认',await page.locator('dialog[open]').count()===1);await page.locator('[data-action=close-modal]').click();await submit('node');
 await assert('蓝图版本与节点保存',(await stored('aurora.blueprintVersion'))===4 && (await stored('aurora.node.evaluation')).concurrency==='7');
 await visit('/p/aurora/pilot');await page.locator('input[name=count]').fill('12');await submit('pilot');await page.waitForFunction(()=>route.endsWith('/runs/p03'));
 await assert('12 条试制独立 P03，不伪造完成',(await stored('aurora.pilot')).count==='12'&&(await page.locator('main').innerText()).includes('已排队'));
 await visit('/p/aurora/compare');await page.locator('[data-action=adopt]').click();await page.locator('[data-action=confirm-modal]').click();await page.waitForFunction(()=>route.endsWith('/runs/new'));
 await page.locator('input[name=count]').fill('500');await page.locator('input[name=budget]').fill('80');await submit('scale');await page.waitForFunction(()=>route.endsWith('/runs/b19'));
 await assert('扩量先规划后创建 B19',(await stored('aurora.scale')).budget==='80');
 await visit('/p/aurora/rules');await page.locator('input[name=pattern]').fill('[');await page.locator('[data-action=preview-rule]').click();await assert('无效正则拒绝预览',(await page.locator('#toast').innerText()).includes('无效'));
 await page.locator('input[name=pattern]').fill('对不起');await page.locator('[data-action=preview-rule]').click();await assert('预览命中不改处置',(await page.locator('#rule-preview').innerText()).includes('1 / 3')&&!(await stored('aurora.decision.s104')));await submit('rules');
 await visit('/p/aurora/review');await assert('默认队列仅待审阅',await page.locator('tbody tr').count()===1);await page.locator('[data-sample-filter]').selectOption('全部状态');await page.waitForFunction(()=>document.querySelectorAll('tbody tr').length===3);
 await visit('/p/aurora/releases/new');await submit('release');await page.waitForFunction(()=>route.endsWith('/releases/v1.2'));await page.locator('[data-action=publish]').click();
 await assert('待审阅阻止发布',(await page.locator('dialog').innerText()).includes('仍有待处理'));await page.locator('[data-action=confirm-modal]').click();await page.waitForFunction(()=>route.endsWith('/data/s104'));
 await submit('decision');await assert('判断理由必填',await page.locator('textarea[name=reason]').evaluate(e=>!e.checkValidity()));
 await page.locator('textarea[name=reason]').fill('引用语境人工复查通过，保留来源和边界限制。');await submit('decision');
 await visit('/p/aurora/releases/v1.2');await page.locator('[data-action=publish]').click();await page.locator('[data-action=confirm-modal]').click();
 const frozen=(await stored('aurora.releases'))['v1.2'];
 await assert('发布冻结 3 条样本与配置',frozen.ids.join(',')==='s104,s105,s106'&&frozen.blueprintVersion===4);
 const dl1=page.waitForEvent('download');await page.locator('[data-action=download]').click();const download1=await dl1;await download1.saveAs('/root/llm/output/playwright/studio-v2/qa-sft.jsonl');
 await visit('/p/aurora/data/s104');await page.locator('select[name=decision]').selectOption('已隔离');await page.locator('textarea[name=reason]').fill('下一版本排除；旧发布快照必须保留。');await submit('decision');
 await visit('/p/aurora/releases/v1.2');await assert('后续隔离不改变旧清单',(await page.locator('main').innerText()).includes('s104, s105, s106')&&JSON.stringify((await stored('aurora.releases'))['v1.2'])===JSON.stringify(frozen));
 await page.getByRole('link',{name:'创建下一版本',exact:true}).click();await page.waitForFunction(()=>route.endsWith('/releases/new'));await assert('下一版本自动 v1.3',await page.locator('input[name=version]').inputValue()==='v1.3');await page.locator('select[name=format]').selectOption('CSV');await submit('release');await page.waitForFunction(()=>route.endsWith('/releases/v1.3'));await page.locator('[data-action=publish]').click();await page.locator('[data-action=confirm-modal]').click();
 await assert('v1.3 排除隔离项、v1.2 保留',Object.keys(await stored('aurora.releases')).length===2&&(await stored('aurora.releases'))['v1.3'].ids.join(',')==='s105,s106');
 const dl2=page.waitForEvent('download');await page.locator('[data-action=download]').click();await (await dl2).saveAs('/root/llm/output/playwright/studio-v2/qa-sft.csv');
 await visit('/p/boreal/releases/new');await submit('release');await page.waitForFunction(()=>route.endsWith('/releases/v1.2'));await page.locator('[data-action=publish]').click();await page.locator('[data-action=confirm-modal]').click();const dl3=page.waitForEvent('download');await page.locator('[data-action=download]').click();await (await dl3).saveAs('/root/llm/output/playwright/studio-v2/qa-grpo.jsonl');
 await assert('GRPO 发布 g201',(await stored('boreal.releases'))['v1.2'].ids.join(',')==='g201');
 await page.locator('#role').selectOption('viewer');await visit('/settings/connections');await assert('访客设置拒绝',(await page.locator('h1').innerText()).includes('没有访问权限'));
 await visit('/p/aurora/data/s105');await assert('访客表单不可保存',await page.locator('form input,form textarea,form select,form button').evaluateAll(els=>els.every(e=>e.disabled)));
 await page.keyboard.press('ControlOrMeta+K');await page.locator('#command-input').fill('质量');await assert('命令搜索结果',await page.locator('.command-link').count()>0);await page.keyboard.press('Escape');
 await page.setViewportSize({width:390,height:844});await visit('/p/aurora/blueprint');await assert('390px 蓝图无全页溢出',await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
 await visit('/p/aurora/data/s104');await assert('390px 审阅无全页溢出',await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
 await assert('无 JavaScript 异常',errors.length===0);
 return {count:results.length,results,errors};
}
